import{_ as t,o as p,c as a,a5 as o}from"./chunks/framework.DJo0M80U.js";const n=JSON.parse('{"title":"自定义SQL","description":"","frontmatter":{"title":"自定义SQL","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/自定义SQL.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/自定义SQL.md"}'),r={name:"posts/java快速入门/附录/未分类/一发入魂/自定义SQL.md"};function m(s,e,i,l,c,d){return p(),a("div",null,[...e[0]||(e[0]=[o('<div><p>当<code>mp</code>提供的方法还不能满足需求时，则可以自定义<code>SQL</code>。</p><p>原生<code>mybatis</code> 示例如下 注解方式</p><p>packagecom.example.mp.mappers; importcom.baomidou.mybatisplus.core.mapper.BaseMapper; importcom.example.mp.po.User; importorg.apache.ibatis.annotations.Select; importjava.util.List; /**</p><ul><li>@Authoryogurtzzz</li><li>@Date2021/3/18 11:21 **/public</li></ul><p>interface UserMapper</p><p><code>extends</code> <code>BaseMapper\\&lt;User\\&gt; {</code></p><p>@Select(&quot;select * from user&quot;) List&lt;User&gt; selectRaw(); }</p><p><code>xml</code>方式</p><p>&lt;?xml version=&quot;1.0&quot;encoding=&quot;UTF-8&quot;?&gt;&lt;!DOCTYPE mapperPUBLIC&quot;-<a href="//mybatis.org//DTD" target="_blank" rel="noreferrer">//mybatis.org//DTD</a> Mapper 3.0//EN&quot;&quot;<a href="http://mybatis.org/dtd/mybatis-3-mapper.dtd" target="_blank" rel="noreferrer">http://mybatis.org/dtd/mybatis-3-mapper.dtd</a>&quot;&gt; &lt;mapper namespace=&quot;com.example.mp.mappers.UserMapper&quot;&gt; &lt;select</p><p>id=&quot;selectRaw&quot;resultType=&quot;com.example.mp.po.User&quot;&gt; SELECT * FROM user &lt;/select&gt; &lt;/mapper&gt;</p><p>packagecom.example.mp.mappers; importcom.baomidou.mybatisplus.core.mapper.BaseMapper; importcom.example.mp.po.User; importorg.apache.ibatis.annotations.Select; importjava.util.List; Public</p><p>interface UserMapper extends BaseMapper&lt;User&gt; { List&lt;User&gt; selectRaw(); } 使用<code>xml</code>时，若<code>xml</code>文件与<code>mapper</code>接口文件不在同一目录下，则需要在<code>application.yml</code>中配置<code>mapper.xml</code>的存放路径</p><p>mybatis-plus: mapper-locations:/mappers/* 若有多个地方存放<code>mapper</code>，则用数组形式进行配置</p><p>mybatis-plus: mapper-locations: -/mappers/* -/com/example/mp/* 测试代码如下</p><p>@TestpublicvoidtestCustomRawSql(){ List&lt;User&gt; users = userMapper.selectRaw(); users.forEach(System.out::println); } 结果 <code>mybatis-plus</code> 也可以使用<code>mp</code>提供的<code>Wrapper</code>条件构造器，来自定义<code>SQL</code> 示例如下 注解方式</p><p>import com.baomidou.mybatisplus.core.conditions.Wrapper; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.baomidou.mybatisplus.core.toolkit.Constants; import com.example.mp.po.User; import org.apache.ibatis.annotations.Param; import org.apache.ibatis.annotations.Select; import java.util.List; public interface UserMapper extends BaseMapper&lt;User&gt; {</p><p>// SQL 中不写<code>WHERE</code>关键字，且固定使用<code>${ew.customSqlSegment}</code></p><p>@Select(&quot;select * from user ${ew.customSqlSegment}&quot;)</p><p>List&lt;User&gt; findAll(@Param(Constants.WRAPPER) Wrapper&lt;User&gt; wrapper); } packagecom.example.mp.mappers; importcom.baomidou.mybatisplus.core.conditions.Wrapper; importcom.baomidou.mybatisplus.core.mapper.BaseMapper; importcom.baomidou.mybatisplus.core.toolkit.Constants; importcom.example.mp.po.User; importorg.apache.ibatis.annotations.Param; importorg.apache.ibatis.annotations.Select; importjava.util.List; publicinterfaceUserMapperextendsBaseMapper&lt;User&gt; { // SQL 中不写<code>WHERE</code>关键字，且固定使用</p><p>${ew.customSqlSegment}@Select(&quot;select * from user ${ew.customSqlSegment}&quot;)List&lt;User&gt; findAll(@Param(Constants.WRAPPER)Wrapper&lt;User&gt; wrapper); }</p><p><code>xml</code>方式</p><p>package com.example.mp.mappers; import com.baomidou.mybatisplus.core.conditions.Wrapper; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.example.mp.po.User; import java.util.List; public interface UserMapper extends BaseMapper&lt;User&gt; {</p><p>List&lt;User&gt; findAll(Wrapper&lt;User&gt; wrapper); }</p><p>&lt;!-- UserMapper.xml --&gt; &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;!DOCTYPE mapper PUBLIC &quot;-<a href="//mybatis.org//DTD" target="_blank" rel="noreferrer">//mybatis.org//DTD</a> Mapper 3.0//EN&quot; &quot;<a href="http://mybatis.org/dtd/mybatis-3-mapper.dtd" target="_blank" rel="noreferrer">http://mybatis.org/dtd/mybatis-3-mapper.dtd</a>&quot;&gt; &lt;mapper namespace=&quot;com.example.mp.mappers.UserMapper&quot;&gt;</p><p>&lt;select id=&quot;findAll&quot; resultType=&quot;com.example.mp.po.User&quot;&gt;</p><p>SELECT * FROM user ${ew.customSqlSegment}</p><p>&lt;/select&gt; &lt;/mapper&gt; <strong>sxxx</strong></p><p>packagecom.example.mp.mappers; importcom.baomidou.mybatisplus.core.conditions.Wrapper; importcom.baomidou.mybatisplus.core.mapper.BaseMapper; importcom.example.mp.po.User; importjava.util.List; publicinterfaceUserMapperextendsBaseMapper&lt;User&gt; { List&lt;User&gt; findAll(Wrapper&lt;User&gt; wrapper); } 复制代码</p><p>&lt;!-- UserMapper.xml --&gt;&lt;?xml version=&quot;1.0&quot;encoding=&quot;UTF-8&quot;?&gt;&lt;!DOCTYPE mapperPUBLIC&quot;-<a href="//mybatis.org//DTD" target="_blank" rel="noreferrer">//mybatis.org//DTD</a> Mapper 3.0//EN&quot;&quot;<a href="http://mybatis.org/dtd/mybatis-3-mapper.dtd%22%5C%3E%5C%3Cmappernamespace=%22com.example.mp.mappers.UserMapper%22%5C%3E%5C%3Cselectid=%22findAll%22resultType=%22com.example.mp.po.User" target="_blank" rel="noreferrer">http://mybatis.org/dtd/mybatis-3-mapper.dtd&quot;\\&gt;\\&lt;mappernamespace=&quot;com.example.mp.mappers.UserMapper&quot;\\&gt;\\&lt;selectid=&quot;findAll&quot;resultType=&quot;com.example.mp.po.User</a>&quot;&gt;SELECT * FROM user ${ew.customSqlSegment} &lt;/select&gt;&lt;/mapper&gt; 复制代码</p><p><code></code></p></div>',1)])])}const g=t(r,[["render",m]]);export{n as __pageData,g as default};
